package miniprogram

import (
	"context"
)

// CheckEncryptedMessageRequest verifies that an encrypted data blob was
// produced for this Mini Program. It is used by the privacy-oriented APIs
// (e.g. the new user-info flows) where the server must confirm the data was not
// generated by another app.
type CheckEncryptedMessageRequest struct {
	// EncryptedMsgHash is the SHA-256 hash of the encrypted message received
	// from the client.
	EncryptedMsgHash string `json:"encrypted_msg_hash"`
}

// CheckEncryptedMessage tells the server whether an encrypted message hash was
// indeed produced by WeChat for this Mini Program.
//
// Reference: https://developers.weixin.qq.com/miniprogram/dev/server/API/user-info/basic-info/api_checkencrypteddata.html
func (w *MiniProgram) CheckEncryptedMessage(ctx context.Context, encryptedMsgHash string) error {
	return w.withAccessTokenPost(ctx, "/wxa/business/checkencryptedmsg", nil, defaultReqOptions(), &CheckEncryptedMessageRequest{EncryptedMsgHash: encryptedMsgHash}, nil)
}
